    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: "Visceral" abdominal pain is usually described as _____ and is _____ localized.', '["Sharp; well", "Dull/Aching; poorly", "Burning; well", "Tearing; poorly"]', 1, 'Caused by stretching or contraction of hollow organs, usually felt in the midline (epigastric, umbilical, or suprapubic).'),
    (v_topic_id, '202: "Parietal" abdominal pain is usually described as _____ and is _____ localized.', '["Dull; poorly", "Sharp/Steady; well", "Crampy; poorly", "Itchy; well"]', 1, 'Caused by inflammation of the parietal peritoneum; the patient typically wants to stay very still.'),
    (v_topic_id, '203: "Referred Pain" to the "Right Shoulder" in a patient with abdominal pain suggests irritation of the:', '["Kidney", "Diaphragm (e.g., from Gallbladder or Liver disease)", "Spleen", "Appendix"]', 1, 'Mediated by the phrenic nerve (C3, C4, C5).'),
    (v_topic_id, '204: Abdominal pain that is "Sudden" and "Maximal at onset" suggests:', '["Appendicitis", "Perforation, Torsion, or Vascular catastrophe (e.g., AAA)", "Diverticulitis", "Gastroenteritis"]', 1, 'Gradual onset is more typical of inflammation or infection.'),
    (v_topic_id, '205: "Epigastric" pain relieved by food is a classic "Representation" for:', '["Gastric Ulcer", "Duodenal Ulcer", "Pancreatitis", "Cholecystitis"]', 1, 'Food triggers bicarbonate secretion which neutralizes acid in the duodenum; gastric ulcers often hurt MORE with food.'),
    (v_topic_id, '206: "Right Upper Quadrant" (RUQ) pain + Fever + Jaundice is known as _____ and suggests _____:', '["Beck''s Triad; Tamponade", "Charcot''s Triad; Acute Cholangitis", "Whipple''s Triad; Insulinoma", "Saint''s Triad; Hernia"]', 1, 'This is a surgical emergency indicating infection of the biliary tree.'),
    (v_topic_id, '207: "Reynolds'' Pentad" adds which two findings to Charcot''s Triad?', '["Nausea and Vomiting", "Hypotension and Altered Mental Status", "Diarrhea and Rash", "Cough and Dyspnea"]', 1, 'Indicates severe obstructive suppurative cholangitis.'),
    (v_topic_id, '208: "Murphy''s Sign" (arrest of inspiration on RUQ palpation) is a high-yield test for:', '["Hepatitis", "Acute Cholecystitis", "Appendicitis", "Pancreatitis"]', 1, 'Highly specific for gallbladder inflammation.'),
    (v_topic_id, '209: Abdominal pain radiating to the "Back" is a classic clue for:', '["Appendicitis", "Acute Pancreatitis or Aortic Aneurysm", "Cystitis", "Small bowel obstruction"]', 1, 'Reflects the retroperitoneal location of these structures.'),
    (v_topic_id, '210: "Perumbilical" pain that migrates to the "Right Lower Quadrant" (RLQ) is the classic story for:', '["Cholecystitis", "Acute Appendicitis", "Diverticulitis", "Renal colic"]', 1, 'Initial visceral pain (umbilical) followed by parietal pain (McBurney''s point) as the peritoneum becomes involved.'),
    (v_topic_id, '211: "McBurney''s Point" is located:', '["In the RUQ", "One-third of the distance from the ASIS to the umbilicus", "In the left groin", "In the epigastrium"]', 1, 'The site of maximal tenderness in appendicitis.'),
    (v_topic_id, '212: "Rovsing''s Sign" in appendicitis is:', '["Pain in the RLQ when the LLQ is palpated", "Pain on internal rotation of the hip", "Pain on extension of the hip", "Rebound tenderness"]', 0, 'Referred rebound tenderness.'),
    (v_topic_id, '213: "Psoas Sign" (pain on hip extension) suggests an appendix that is:', '["Normal", "Retrocecal (lying against the psoas muscle)", "Ruptured", "In the pelvis"]', 1, 'A high-yield anatomical clinical correlation.'),
    (v_topic_id, '214: "Left Lower Quadrant" (LLQ) pain in an older patient is "Left-sided appendicitis," also known as:', '["Crohn''s disease", "Acute Diverticulitis", "Ulcerative colitis", "Ischemic colitis"]', 1, 'Inflammation of colonic diverticula.'),
    (v_topic_id, '215: "Pain out of proportion to exam" in an older patient with atrial fibrillation is:', '["Appendicitis", "Acute Mesenteric Ischemia", "Small bowel obstruction", "Volvulus"]', 1, 'A high-stakes "representation" for vascular compromise of the gut.'),
    (v_topic_id, '216: "Hematemesis" (vomiting blood) indicates bleeding _____ the Ligament of Treitz.', '["Above", "Below", "At", "Near"]', 0, 'Upper GI bleeding.'),
    (v_topic_id, '217: "Melena" (black, tarry stools) usually indicates bleeding from the:', '["Colon", "Upper GI tract (stomach or duodenum)", "Anus", "Small bowel"]', 1, 'Blood is digested/oxidized by acid and bacteria, turning it black.'),
    (v_topic_id, '218: "Hematochezia" (bright red blood per rectum) usually indicates:', '["Upper GI bleed", "Lower GI bleed (colon or rectum)", "Stomach cancer", "Esophagitis"]', 1, 'Can be from a very rapid upper GI bleed (Brisk bleed), but usually colonic.'),
    (v_topic_id, '219: A "BUN to Creatinine ratio" > 30:1 in a patient with GI bleeding suggests:', '["Lower GI bleed", "Upper GI bleed (blood is digested and urea is absorbed)", "Renal failure", "Liver failure"]', 1, 'Digestion of blood proteins leads to increased urea production.'),
    (v_topic_id, '220: "Obturator Sign" (pain on internal rotation of the flexed hip) suggests:', '["Cholecystitis", "Pelvic Appendix", "Kidney stone", "Hernia"]', 1, 'The appendix is lying near the obturator internus muscle.'),
    (v_topic_id, '221: "Cullen''s Sign" (periumbilical ecchymosis) and "Grey Turner''s Sign" (flank ecchymosis) suggest:', '["Liver failure", "Retroperitoneal Hemorrhage (e.g., severe hemorrhagic pancreatitis)", "Appendicitis", "Trauma"]', 1, 'Blood tracks along the fascial planes to the skin.'),
    (v_topic_id, '222: "Courvoisier''s Law" states that a palpable, non-tender gallbladder in a jaundiced patient suggests:', '["Gallstones", "Malignancy (e.g., Pancreatic cancer) obstructing the common bile duct", "Hepatitis", "Normal"]', 1, 'Gallstones usually cause a scarred, shrunken gallbladder that is not palpable.'),
    (v_topic_id, '223: "Scaphoid" abdomen (sunken appearance) in a newborn with respiratory distress suggests:', '["Normal", "Congenital Diaphragmatic Hernia", "Gastroschisis", "Omphalocele"]', 1, 'Abdominal contents have moved into the chest.'),
    (v_topic_id, '224: "Vomiting" that is "Non-bilious" and "Projectile" in a 3-week-old infant is:', '["GERD", "Hypertrophic Pyloric Stenosis", "Intussusception", "Volvulus"]', 1, 'The obstruction is proximal to the Ampulla of Vater.'),
    (v_topic_id, '225: "Vomiting" that is "Bilious" in a neonate is a sign of:', '["Pyloric stenosis", "Intestinal obstruction (e.g., Malrotation/Volvulus) below the Ampulla of Vater", "Overfeeding", "Milk allergy"]', 1, 'A surgical emergency until proven otherwise.'),
    (v_topic_id, '226: "Currant Jelly" stools in a child with intermittent abdominal pain suggests:', '["Constipation", "Intussusception", "Appendicitis", "Meckel''s diverticulum"]', 1, 'Sloughing of the ischemic mucosa and mucus.'),
    (v_topic_id, '227: "Painless" bright red rectal bleeding in a 2-year-old is the classic story for:', '["Intussusception", "Meckel''s Diverticulum", "Anal fissure", "Polyp"]', 1, 'Heterotopic gastric mucosa in the diverticulum causes ulceration of the adjacent ileum.'),
    (v_topic_id, '228: "Tenesmus" (painful, ineffective straining to defecate) is characteristic of:', '["Irritable Bowel Syndrome", "Inflammatory Bowel Disease (especially Ulcerative Colitis) or Rectal Cancer", "Constipation", "GERD"]', 1, 'Indicates inflammation or a mass in the rectum.'),
    (v_topic_id, '229: "Large Volume" watery diarrhea that persists during fasting suggests:', '["Osmotic diarrhea", "Secretory diarrhea", "Infection", "Malabsorption"]', 1, 'Example: Cholera or VIPoma.'),
    (v_topic_id, '230: "Osmotic" diarrhea (e.g., Lactose Intolerance) typically _____ when the patient stops eating.', '["Worsens", "Improves/Resolves", "Stays the same", "Bleeds"]', 1, 'The non-absorbable solute is no longer in the gut to pull water in.'),
    (v_topic_id, '231: "Steatorrhea" (greasy, foul-smelling, floating stools) is a sign of:', '["Protein malabsorption", "Fat Malabsorption (e.g., Celiac or Pancreatic Insufficiency)", "Blood in stool", "Infection"]', 1, 'Often accompanied by weight loss and vitamin deficiencies.'),
    (v_topic_id, '232: "Hematuria" that occurs throughout the entire stream of urination suggests bleeding from the:', '["Urethra", "Bladder or Kidney", "Prostate", "None"]', 1, 'Total hematuria.'),
    (v_topic_id, '233: "Initial" hematuria (blood only at the start) suggests bleeding from the:', '["Kidney", "Urethra", "Bladder neck", "Ureter"]', 1, 'The blood is "washed out" by the first part of the stream.'),
    (v_topic_id, '234: "Terminal" hematuria (blood only at the end) suggests bleeding from the:', '["Kidney", "Bladder neck or Prostate", "Urethra", "Stomach"]', 1, 'Contraction of the bladder at the end of voiding squeezes the bleeding site.'),
    (v_topic_id, '235: "Painless Hematuria" in an older patient (especially a smoker) is _____ until proven otherwise.', '["Kidney stone", "Bladder or Renal Malignancy", "UTI", "Prostatitis"]', 1, 'A high-stakes "zebra" that must be ruled out with cystoscopy/imaging.'),
    (v_topic_id, '236: "Renal Colic" is characterized by severe pain radiating from the:', '["Shoulder to back", "Flank to the groin", "Epigastrium to back", "Umbilicus to RLQ"]', 1, 'Matches the "Representativeness" for a passing kidney stone.'),
    (v_topic_id, '237: "Costovertebral Angle (CVA) Tenderness" is a classic finding in:', '["Cystitis", "Pyelonephritis", "Renal stones", "Gallstones"]', 1, 'Indicates inflammation of the kidney itself.'),
    (v_topic_id, '238: "Oliguria" is defined as a urine output less than:', '["100 mL/day", "400 to 500 mL/day", "1000 mL/day", "Zero"]', 1, 'Anuria is < 100 mL/day.'),
    (v_topic_id, '239: A "Kidney Stone" that is "Radiolucent" (not visible on plain X-ray) is usually:', '["Calcium oxalate", "Uric Acid", "Struvite", "Cystine"]', 1, 'Requires CT for visualization.'),
    (v_topic_id, '240: "Prerenal Azotemia" is most commonly caused by:', '["Stones", "Hypovolemia (Dehydration, Hemorrhage) or Low Cardiac Output", "Antibiotics", "Diabetes"]', 1, 'Reduced blood flow to the kidneys.'),
    (v_topic_id, '241: "Acute Tubular Necrosis" (ATN) is an _____ cause of AKI.', '["Prerenal", "Intrinsic", "Postrenal", "Normal"]', 1, 'Often due to prolonged ischemia or toxins (e.g., aminoglycosides, contrast).'),
    (v_topic_id, '242: "Acute Interstitial Nephritis" (AIN) often presents with Fever, Rash, and _____ in the urine.', '["Blood", "Eosinophils", "Sugar", "Casts"]', 1, 'Classically triggered by drugs (e.g., Penicillins, NSAIDs, PPIs).'),
    (v_topic_id, '243: "Postrenal" AKI is caused by:', '["Shock", "Obstruction (e.g., BPH, Stones, Tumor)", "Glomerulonephritis", "Dehydration"]', 1, 'Bilateral obstruction is required for the creatinine to rise significantly in a patient with two kidneys.'),
    (v_topic_id, '244: "Nephrotic Syndrome" is characterized by proteinuria > _____ g/day.', '["1.0", "3.5", "10", "Zero"]', 1, 'Accompanied by edema and hypoalbuminemia.'),
    (v_topic_id, '245: "Nephritic Syndrome" is characterized by hematuria, hypertension, and _____:', '["Massive edema", "RBC Casts in the urine", "Weight loss", "High glucose"]', 1, 'Indicates glomerular inflammation.'),
    (v_topic_id, '246: "IgA Nephropathy" (Berger Disease) classically presents as hematuria following a:', '["Fatty meal", "Upper Respiratory Infection (URI)", "Trauma", "Drug use"]', 1, 'A "synpharyngitic" hematuria.'),
    (v_topic_id, '247: "Post-Streptococcal Glomerulonephritis" (PSGN) presents hematuria _____ after a strep throat infection.', '["1-2 days", "1-3 weeks", "6 months", "Immediately"]', 1, 'Unlike IgA nephropathy, there is a distinct latent period.'),
    (v_topic_id, '248: "Goodpasture Syndrome" is a "Pulmonary-Renal Syndrome" characterized by Hemoptysis and _____:', '["Abdominal pain", "Glomerulonephritis (Hematuria)", "Diarrhea", "Leg swelling"]', 1, 'Caused by anti-GBM antibodies.'),
    (v_topic_id, '249: "Alport Syndrome" is a genetic defect in collagen that presents with Hematuria and _____:', '["Blindness", "Sensorineural Hearing Loss", "Heart failure", "Liver failure"]', 1, '"Can''t see, can''t pee, can''t hear a buzzing bee."'),
    (v_topic_id, '250: "Hepatitis B" infection is associated with which nephrotic syndrome?', '["Minimal Change Disease", "Membranous Nephropathy", "FSGS", "Amyloidosis"]', 1, 'One of many viral associations with renal disease.'),
    (v_topic_id, '251: "HIV" infection is associated with which nephrotic syndrome?', '["Minimal Change", "Collapsing FSGS", "Membranous", "Post-strep"]', 1, 'FSGS = Focal Segmental Glomerulosclerosis.'),
    (v_topic_id, '252: "Minimal Change Disease" is the most common cause of nephrotic syndrome in:', '["Elderly", "Children", "Diabetics", "IV drug users"]', 1, 'Responds very well to steroids.'),
    (v_topic_id, '253: "Ascites" (fluid in the abdomen) is best detected on physical exam by which two maneuvers?', '["Rebound and Guarding", "Shifting Dullness and Fluid Wave", "Murphy and Rovsing", "Palpation and Auscultation"]', 1, 'Shifting dullness is the more sensitive of the two.'),
    (v_topic_id, '254: "Sister Mary Joseph Nodule" is a palpable node at the _____ suggesting _____:', '["Neck; Lymphoma", "Umbilicus; Metastatic intra-abdominal malignancy", "Axilla; Breast cancer", "Groin; Hernia"]', 1, 'Classically associated with gastric or pancreatic cancer.'),
    (v_topic_id, '255: "Virchow''s Node" is a palpable left _____ node suggesting gastric cancer.', '["Axillary", "Supraclavicular", "Inguinal", "Cervical"]', 1, 'A high-yield physical exam clue.'),
    (v_topic_id, '256: "Trosier''s Sign" is the finding of:', '["A palpable gallbladder", "Virchow''s node", "Aumbilical nodule", "Flank bruising"]', 1, 'Synonymous with the left supraclavicular node in gastric cancer.'),
    (v_topic_id, '257: "Irish''s Node" is a palpable left _____ node suggesting gastric cancer.', '["Supraclavicular", "Axillary", "Cervical", "Inguinal"]', 1, 'Another site for sentinel metastasis.'),
    (v_topic_id, '258: "Blumer''s Shelf" is a palpable mass in the _____ felt on rectal exam.', '["Rectum", "Rectovesical or Rectouterine pouch (suggesting metastatic cancer)", "Prostate", "Bladder"]', 1, 'Indicates "drop metastasis" from an upper GI tumor.'),
    (v_topic_id, '259: "Krukenberg Tumor" is a metastatic tumor to the _____ from the GI tract.', '["Liver", "Ovary", "Lung", "Brain"]', 1, 'Usually contains signet ring cells.'),
    (v_topic_id, '260: "Abdominal Pain" + "Diarrhea" + "Weight Loss" in a young person with perianal fistulas is:', '["Ulcerative Colitis", "Crohn''s Disease", "IBS", "Celiac disease"]', 1, 'Crohn''s can affect any part of the GI tract and is transmural.'),
    (v_topic_id, '261: "Bloody Diarrhea" + "Tenesmus" + "Continuous colonic involvement" starting in the rectum is:', '["Crohn''s Disease", "Ulcerative Colitis", "Infectious diarrhea", "Ischemic colitis"]', 1, 'UC is limited to the mucosa and submucosa of the colon.'),
    (v_topic_id, '262: "Painless Jaundice" in an older patient is _____ until proven otherwise.', '["Hepatitis", "Pancreatic Head Cancer (obstructing the bile duct)", "Gallstones", "Gilbert syndrome"]', 1, 'A "high-stakes" differential.'),
    (v_topic_id, '263: "Abdominal Pain" relieved by a "Bowel movement" is a key feature of:', '["Appendicitis", "Irritable Bowel Syndrome (IBS)", "IBD", "Colon cancer"]', 1, 'Part of the Rome criteria for IBS.'),
    (v_topic_id, '264: "Ischemic Colitis" typically presents with pain and bloody diarrhea in which location?', '["RLQ", "Splenic Flexure (watershed area)", "Epigastrium", "Rectum"]', 1, 'The splenic flexure and rectosigmoid junction are the most vulnerable areas.'),
    (v_topic_id, '265: "Obstipation" (inability to pass both stool and flatus) is a sign of:', '["Constipation", "Complete Bowel Obstruction", "IBS", "Diarrhea"]', 1, 'Requires urgent surgical evaluation.'),
    (v_topic_id, '266: "Small Bowel Obstruction" (SBO) classically presents with "Tinkling" bowel sounds and _____ on X-ray:', '["Air under the diaphragm", "Dilated loops of bowel with Air-Fluid levels", "Lead pipe colon", "Thumbprinting"]', 1, 'Most common cause is adhesions from previous surgery.'),
    (v_topic_id, '267: "Large Bowel Obstruction" (LBO) in an older patient is most commonly due to:', '["Adhesions", "Colon Cancer", "Volvulus", "Hernia"]', 1, 'Adhesions are the most common cause of SBO; cancer is the most common for LBO.'),
    (v_topic_id, '268: "Volvulus" (twisting of the bowel) classically shows a _____ sign on X-ray.', '["Thumbprint", "Coffee Bean", "Lead pipe", "String"]', 1, 'Most common in the sigmoid colon (elderly) or cecum.'),
    (v_topic_id, '269: "String Sign" on a barium swallow or follow-through suggests:', '["Normal gut", "Crohn''s Disease (narrowing of the terminal ileum) or Pyloric Stenosis", "UC", "Cancer"]', 1, 'Reflects severe luminal narrowing.'),
    (v_topic_id, '270: "Lead Pipe Colon" (loss of haustra) on imaging is a sign of chronic:', '["Crohn''s disease", "Ulcerative Colitis", "IBS", "Diverticulosis"]', 1, 'The colon becomes a smooth, featureless tube.'),
    (v_topic_id, '271: "Pseudo-obstruction" of the colon in a sick, elderly patient is called:', '["Volvulus", "Ogilvie Syndrome", "Hirschsprung disease", "IBS"]', 1, 'Massive colonic dilation without a mechanical blockage.'),
    (v_topic_id, '272: "Abdominal Pain" + "Vomiting" + "High-pitched bowel sounds" + "History of surgery" =', '["Appendicitis", "Small Bowel Obstruction (due to adhesions)", "Cholecystitis", "Pancreatitis"]', 1, 'A classic clinical constellation.'),
    (v_topic_id, '273: "Epigastric pain" that radiates to the back and is "Improved by leaning forward" is:', '["Pericarditis", "Acute Pancreatitis", "GERD", "Gastric ulcer"]', 1, 'The leaning position takes the pressure off the retroperitoneal pancreas.'),
    (v_topic_id, '274: "Gallstone Ileus" is caused by a gallstone obstructing the:', '["Common bile duct", "Ileocecal valve (after eroding through the gallbladder wall into the gut)", "Stomach", "Rectum"]', 1, 'Classic triad: SBO, gallstone in the gut, and air in the biliary tree (pneumobilia).'),
    (v_topic_id, '275: "Pneumoperitoneum" (free air under the diaphragm) on upright CXR indicates:', '["Pneumonia", "Perforated Viscus (e.g., Ulcer, Diverticulum)", "Normal post-op state", "Both B and C"]', 3, 'Always a surgical emergency unless it''s expected after recent laparotomy.'),
    (v_topic_id, '276: "Acanthosis Nigricans" (velvety dark skin in folds) can be a benign sign of insulin resistance or a sign of:', '["Heart failure", "Gastric Adenocarcinoma (Malignant Acanthosis Nigricans)", "Lung cancer", "Liver failure"]', 1, 'A paraneoplastic syndrome.'),
    (v_topic_id, '277: "Pruritus" (itching) + "Jaundice" suggests:', '["Acute Viral Hepatitis", "Obstructive Jaundice (Bile salts depositing in skin)", "Anemia", "Renal stones"]', 1, 'Common in primary biliary cholangitis or pancreatic cancer.'),
    (v_topic_id, '278: "Splenomegaly" + "Anemia" + "Thrombocytopenia" is a sign of _____ in a cirrhotic patient.', '["Infection", "Hypersplenism (sequestration of cells in the enlarged spleen)", "Marrow failure", "Leukemia"]', 1, 'Portal hypertension causes the spleen to enlarge.'),
    (v_topic_id, '279: "Spider Angiomata," "Palmar Erythema," and "Gynecomastia" are signs of:', '["Renal failure", "Liver Cirrhosis (Hyperestrogenism)", "Heart failure", "Lung cancer"]', 1, 'The liver fails to metabolize estrogen.'),
    (v_topic_id, '280: "Caput Medusae" (dilated veins on the abdomen) is a sign of:', '["Inferior Vena Cava obstruction", "Portal Hypertension (re-opening of the umbilical vein)", "Obesity", "Pregnancy"]', 1, 'One of the portosystemic collateral pathways.'),
    (v_topic_id, '281: "Left Upper Quadrant" (LUQ) pain radiating to the left shoulder after trauma is:', '["Appendicitis", "Splenic Rupture (Kehr''s Sign)", "Kidney stone", "Pneumonia"]', 1, 'Blood irritates the left diaphragm.'),
    (v_topic_id, '282: "Hematuria" + "Flank Pain" + "Palpable Abdominal Mass" is the classic triad for:', '["Kidney stone", "Renal Cell Carcinoma", "Polycystic Kidney Disease", "Bladder cancer"]', 1, 'Only present in a minority of patients.'),
    (v_topic_id, '283: "Left-sided Varicocele" that does not resolve when lying down should prompt evaluation for:', '["Testicular cancer", "Renal Cell Carcinoma (blocking the renal vein)", "Hernia", "Hydrocele"]', 1, 'The left gonadal vein drains into the left renal vein.'),
    (v_topic_id, '284: "Flank Pain" + "Hematuria" + "Fever" + "History of sickle cell trait" suggests:', '["Kidney stone", "Renal Papillary Necrosis", "Pyelonephritis", "Cancer"]', 1, 'Ischemia of the renal papillae causes them to slough and obstruct the ureter.'),
    (v_topic_id, '285: "Dysuria" (painful urination) in a young woman with "Suprapubic tenderness" but NO flank pain is:', '["Pyelonephritis", "Cystitis", "Vaginitis", "Stones"]', 1, 'Infection limited to the bladder.'),
    (v_topic_id, '286: "Abdominal Pain" + "Dark Urine in the morning" + "Thrombosis" =', '["PNH (Paroxysmal Nocturnal Hemoglobinuria)", "Cirrhosis", "Pancreatitis", "Sepsis"]', 1, 'Hemolysis occurs during sleep as pH drops slightly, activating complement.'),
    (v_topic_id, '287: "Renal Bruit" heard on auscultation of the abdomen suggests:', '["AAA", "Renal Artery Stenosis", "Appendicitis", "Gallstones"]', 1, 'A common cause of secondary hypertension.'),
    (v_topic_id, '288: "Abdominal Pain" + "Bloody Diarrhea" + "Eosinophilia" in a traveler suggests:', '["Crohn''s", "Parasitic Infection (e.g., Strongyloides or Schistosomiasis)", "Salmonella", "Celiac disease"]', 1, 'Eosinophilia is a hallmark of helminthic infections.'),
    (v_topic_id, '289: "Diarrhea" + "Dementia" + "Dermatitis" (the 3 D''s) is:', '["Vitamin B12 deficiency", "Pellagra (Niacin/B3 deficiency)", "Scurvy", "Beriberi"]', 1, 'Often seen in populations with corn-based diets or chronic alcoholism.'),
    (v_topic_id, '290: "Watery Diarrhea" following "Antibiotic use" is _____ until proven otherwise.', '["Celiac disease", "Clostridioides difficile infection", "Lactose intolerance", "IBS"]', 1, 'Check the stool for C. diff toxins.'),
    (v_topic_id, '291: "Weight Loss" + "Early Satiety" (feeling full quickly) + "Epigastric pain" is concerning for:', '["GERD", "Gastric Cancer", "Diabetes", "Anorexia"]', 1, 'The tumor reduces the volume/distensibility of the stomach.'),
    (v_topic_id, '292: "Hematuria" + "Cough" + "Nasal ulcers/sinusitis" suggests:', '["Goodpasture", "Granulomatosis with Polyangiitis (Wegener''s)", "SLE", "Lung cancer"]', 1, 'A small-vessel vasculitis.'),
    (v_topic_id, '293: "Joint Pain" + "Abdominal Pain" + "Purpuric rash on legs" in a child is:', '["Lupus", "Henoch-Sch\u00f6nlein Purpura (IgA Vasculitis)", "RA", "Septicemia"]', 1, 'The most common vasculitis in children.'),
    (v_topic_id, '294: "Edema" of the legs + "Periorbital Puffiness" + "Foamy urine" suggests:', '["Heart failure", "Nephrotic Syndrome", "Liver failure", "Normal"]', 1, 'Foamy urine indicates heavy proteinuria.'),
    (v_topic_id, '295: "Dysphagia" (difficulty swallowing) to "Solids only" that is progressive suggests:', '["Achalasia", "Mechanical Obstruction (e.g., Esophageal Cancer or Stricture)", "Stroke", "Anxiety"]', 1, 'Solids-only suggests a physical narrowing; solids and liquids suggests a motility disorder.'),
    (v_topic_id, '296: "Dysphagia" to both "Solids and Liquids" from the start suggests:', '["Esophageal Cancer", "Motility Disorder (e.g., Achalasia or Diffuse Esophageal Spasm)", "Foreign body", "Goiter"]', 1, 'Loss of peristalsis.'),
    (v_topic_id, '297: "Bird''s Beak" appearance on barium swallow is classic for:', '["Esophageal cancer", "Achalasia", "Stricture", "Hiatal hernia"]', 1, 'Reflects the narrow, non-relaxing Lower Esophageal Sphincter.'),
    (v_topic_id, '298: "Odynophagia" (painful swallowing) in an HIV patient is often:', '["Achalasia", "Esophagitis (Candida, CMV, or HSV)", "Cancer", "Stroke"]', 1, 'Requires endoscopy for diagnosis.'),
    (v_topic_id, '299: "Heartburn" that is "Unresponsive to PPIs" should prompt consideration of:', '["Better PPIs", "Eosinophilic Esophagitis or Functional Dyspepsia", "Appendicitis", "Pneumonia"]', 1, 'Often seen in patients with other "atopic" conditions (asthma/allergies).'),
    (v_topic_id, '300: "Hematochezia" in a 70-year-old with "Painless" bleeding is most commonly:', '["Colon cancer", "Diverticulosis or Angiodysplasia", "Hemorrhoids", "Infection"]', 1, 'Diverticular bleeding is the most common cause of brisk lower GI bleeding in the elderly.');
